import { Helmet } from 'react-helmet-async'
import { useParams } from 'react-router'

import {
  Box,
  Container,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  type SelectChangeEvent,
  type Theme,
  Typography,
  useMediaQuery
} from '@mui/material'

import { ALL_SEMESTER_FILTER_VALUE } from 'src/data/semesterFilter'

import PageTitleWrapper from 'src/components/PageTitleWrapper'

import PageHeader from 'src/content/manage/PageHeader'

import { useGetClubAdminReviews, useHideReview, useShowReview } from 'src/hooks/api/review'
import {
  formatSemesterFilterOptionLabel,
  type SemesterFilterValue,
  useSemesterFilteredReviews
} from 'src/hooks/useSemesterFilteredReviews'
import useSafeAuthUser from 'src/hooks/useSafeAuthUser'

import AdminReviewCard from './AdminReviewCard'

const Review: React.FC = () => {
  const { id } = useParams()
  const clubId = Number(id)

  const { userInfo } = useSafeAuthUser()
  const club = userInfo?.clubs.find(c => c.id === clubId)

  const { data: reviews } = useGetClubAdminReviews(clubId)
  const hideReviewMutation = useHideReview(clubId)
  const showReviewMutation = useShowReview(clubId)
  const {
    selectedSemesterFilterValue,
    setSelectedSemesterFilterValue,
    semesterFilterOptions,
    semesterFilteredReviews
  } = useSemesterFilteredReviews(reviews)

  const handleSemesterSelectChange = (event: SelectChangeEvent<string>) => {
    setSelectedSemesterFilterValue(event.target.value as SemesterFilterValue)
  }

  const handleToggleVisibility = (reviewId: number, isHiddenByClub: boolean) => {
    if (isHiddenByClub) {
      showReviewMutation.mutate({ reviewId })
    } else {
      hideReviewMutation.mutate({ reviewId })
    }
  }

  const isUpperThanSm = useMediaQuery((theme: Theme) => theme.breakpoints.up('sm'))

  return (
    <>
      <Helmet>
        <title>후기 관리</title>
      </Helmet>
      <PageTitleWrapper>
        <PageHeader clubName={club?.name ?? ''} />
      </PageTitleWrapper>
      <Container maxWidth="lg" sx={{ px: isUpperThanSm ? 2 : 0 }}>
        <Box display="flex" justifyContent="flex-end" mb={2}>
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <InputLabel id="semester-select-label">학기</InputLabel>
            <Select
              labelId="semester-select-label"
              id="semester-select"
              value={selectedSemesterFilterValue}
              label="학기"
              onChange={handleSemesterSelectChange}
            >
              <MenuItem value={ALL_SEMESTER_FILTER_VALUE}>전체</MenuItem>
              {semesterFilterOptions.map(semesterFilterOption => (
                <MenuItem key={semesterFilterOption} value={semesterFilterOption}>
                  {formatSemesterFilterOptionLabel(semesterFilterOption)}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>
        <Grid container spacing={3}>
          {semesterFilteredReviews?.length ? (
            semesterFilteredReviews.map(review => (
              <Grid item xs={12} key={review.id}>
                <AdminReviewCard {...review} onToggleVisibility={handleToggleVisibility} />
              </Grid>
            ))
          ) : (
            <Grid item xs={12}>
              <Typography align="center" variant="body1" color="text.secondary" sx={{ py: 4 }}>
                등록된 후기가 없습니다.
              </Typography>
            </Grid>
          )}
        </Grid>
      </Container>
    </>
  )
}

export default Review
